    val totals = enabled.associateWith {
        0
    }.toMutableMap()
    for (function in optimized.functions) {
        val before = function.instructions.size
        passes.add("== ${function.name} ==")
        var performed = 0
        for (round in 1..maxRounds) {
            performed = round
            val changes = mutableListOf<String>()
