                changes.add("$name=$count")
                totals[name] = totals.getValue(name) + count
                records.addAll(entries.map {
                    "  $name $it"
                })
            }
            passes.add("round $round: " + changes.joinToString(" "))
            passes.addAll(records)
            if (!changed) break
        }
        passes.add("result: rounds=$performed instructions=$before->${function.instructions.size}")
    }
    val optimizedGraph = callGraph(optimized)
    val analysisLines = graphReport(original, callGraph(original), "original").toMutableList()
    for (function in original.functions) analysisLines.addAll(analysisReport(function, "original"))
    analysisLines.addAll(graphReport(optimized, optimizedGraph, "optimized"))
    val removed = if ("unreachable" in enabled) optimized.functions.indices.filter {
        it !in optimizedGraph.reachable
    }.map {
        optimized.functions[it].name
    } else emptyList()
    optimized.functions = optimized.functions.filter {
        it.name !in removed
    }
    for (function in optimized.functions) analysisLines.addAll(analysisReport(function, "optimized"))
    passes.addAll(listOf("== program ==", "removed functions: " + list(removed), "== total ==", enabled.joinToString(" ") {
        "$it=${totals.getValue(it)}"
    }))
    val allocationLines = mutableListOf<String>()
    val allocated = Program(optimized.arrays, optimized.functions.map {
        allocate(it, registers, allocationLines)
    })
    val runs = File("input/input.txt").readLines().drop(1).map {
        line -> line.split(' ').drop(1).map(String::toLong)
    }
    val programs = listOf(original, optimized, allocated)
    val labels = listOf("original", "optimized", "allocated")
    val comparison = mutableListOf<String>()
    var same = 0
    val totalSteps = IntArray(3)
    val profileSteps = List(3) {
        mutableMapOf<String, Int>()
    }
    val profileCalls = mutableMapOf<String, Int>()
    val dynamicCounts = List(3) {
        kinds.associateWith {
            0
        }.toMutableMap()
    }
    for ((i, input) in runs.withIndex()) {
        comparison.add("run ${i + 1}: inputs=${input.size}")
        val outputs = mutableListOf<List<Long>>()
        for (p in 0..2) {
            val execution = Execution(programs[p], input)
            execution.call("main", emptyList())
            val steps = execution.steps.values.sum()
            val calls = execution.calls.values.sum()
            comparison.add("  ${labels[p]}: steps=$steps calls=$calls output=${list(execution.output.map(Long::toString))}")
            outputs.add(execution.output.toList())
            totalSteps[p] += steps
            for ((name, count) in execution.steps) profileSteps[p][name] = (profileSteps[p][name] ?: 0) + count
            if (p == 0) {
                for ((name, count) in execution.calls) profileCalls[name] = (profileCalls[name] ?: 0) + count
            }
            for (kind in kinds) dynamicCounts[p][kind] = dynamicCounts[p].getValue(kind) + execution.counts.getValue(kind)
        }
        val equal = outputs[0] == outputs[1] && outputs[0] == outputs[2]
        if (equal) same++
        comparison.add("  result: " + if (equal) "same" else "different")
    }
    comparison.add("== profile ==")
    for (function in original.functions) {
        val name = function.name
        comparison.add("$name: calls=${profileCalls[name] ?: 0} original=${profileSteps[0][name] ?: 0} optimized=${profileSteps[1][name] ?: 0} allocated=${profileSteps[2][name] ?: 0}")
    }
    val before = kindCounts(original)
    val after = kindCounts(optimized)
    comparison.addAll(listOf("== summary ==", "runs=${runs.size} same=$same different=${runs.size - same}", "instructions: original=${before.values.sum()} optimized=${after.values.sum()}", "kinds: " + kinds.joinToString(" ") {
        "$it=${before.getValue(it)}->${after.getValue(it)}"
    }, "steps: original=${totalSteps[0]} optimized=${totalSteps[1]} allocated=${totalSteps[2]}"))
    for (p in 0..2) comparison.add("dynamic ${labels[p]}: " + kinds.joinToString(" ") {
        "$it=${dynamicCounts[p].getValue(it)}"
    })
    write("optimized.tac", optimized.text)
    write("analysis.txt", analysisLines)
    write("passes.txt", passes)
    write("regalloc.txt", allocationLines)
    write("comparison.txt", comparison)
}

sealed interface FoldResult {
    data object Unchanged : FoldResult
    data object Deleted : FoldResult
    data class Replacement(val instruction: Instruction) : FoldResult
}
object Optimizations {
    fun fold(instruction: Instruction): FoldResult {
        if (instruction.kind !in listOf("bin", "if")) return FoldResult.Unchanged
        val a = instruction.a!!
        val b = instruction.b!!
        val x = a.constant
        val y = b.constant
        if (x != null && y != null) {
            if (instruction.operation in listOf("/", "%") && y == 0L) return FoldResult.Unchanged
            val value = TacParser.operation(instruction.operation, x, y)
            if (instruction.kind == "if") return if (value == 0L) FoldResult.Deleted else FoldResult.Replacement(Instruction("goto", target = instruction.target))
            return if (value in -2147483648L..2147483647L) FoldResult.Replacement(Instruction.move(instruction.destination!!, Operand.Constant(value))) else FoldResult.Unchanged
        }
        if (instruction.kind != "bin") return FoldResult.Unchanged
        val value = if (instruction.operation == "+" && x == 0L) b else if (instruction.operation in listOf("+", "-") && y == 0L) a else if (instruction.operation == "*" && x == 1L) b else if (instruction.operation in listOf("*", "/") && y == 1L) a else if (instruction.operation == "*" && (x == 0L || y == 0L)) Operand.Constant(0) else null
        return if (value == null) FoldResult.Unchanged else FoldResult.Replacement(Instruction.move(instruction.destination!!, value))
    }
    fun rewrite(function: Function, replacements: Map<Int, List<Instruction>>) {
        val code = mutableListOf<CodeLine>()
        var number = 0
        for (line in function.code) {
            if (line is CodeLine.Label) code.add(line) else {
                val replacement = replacements[number++]
                if (replacement == null) code.add(line) else code.addAll(replacement.map {
                    CodeLine.Code(it)
                })
            }
        }
        function.code = code
    }
    fun temporary(function: Function): String {
        function.temporary++
        return "_t${function.temporary}"
    }
    fun cseRewrite(instruction: Instruction, temporary: String, source: Boolean): List<Instruction> {
        val copy = Instruction.move(instruction.destination!!, Operand.Variable(temporary))
        return if (source) listOf(instruction.copy(destination = temporary), copy) else listOf(copy)
    }
    fun hoist(function: Function, graph: Graph, loop: NaturalLoop, moved: List<Int>): String {
        val h = loop.header
        val outside = graph.blocks[h].predecessors.filter {
            it !in loop.blocks
        }
        val preheader = if (h != 0 && outside.size == 1 && graph.blocks[outside[0]].successors == listOf(h)) outside[0] else null
        val moving = moved.toSet()
        val instructions = graph.instructions
        val insertion = mutableListOf<CodeLine>()
        val codeBefore = function.code.toMutableList()
        val position: Int
        val target: String
        if (preheader != null) {
            val last = graph.blocks[preheader].last
            position = graph.positions[last] + if (instructions[last].kind in listOf("goto", "if")) 0 else 1
            target = "B${preheader + 1}"
        }
        else {
            function.preheader++
            val label = "_p${function.preheader}"
            target = "new $label"
            insertion.add(CodeLine.Label(label))
            var first = graph.positions[graph.blocks[h].first]
            while (first > 0 && function.code[first - 1] is CodeLine.Label) first--
            position = first
            for (p in outside) {
                val index = graph.blocks[p].last
                if (instructions[index].kind in listOf("goto", "if") && instructions[index].target in graph.blocks[h].labels) codeBefore[graph.positions[index]] = CodeLine.Code(instructions[index].copy(target = label))
            }
        }
        insertion.addAll(moved.map {
            CodeLine.Code(instructions[it])
        })
        val code = mutableListOf<CodeLine>()
        var number = 0
        for ((i, line) in codeBefore.withIndex()) {
            if (i == position) code.addAll(insertion)
            if (line is CodeLine.Label) code.add(line) else {
                if (number !in moving) code.add(line)
                number++
            }
        }
        if (position == codeBefore.size) code.addAll(insertion)
        function.code = code
        return target
    }
    fun unreachable(function: Function, graph: Graph): List<String> {
        val records = graph.blocks.indices.filter {
            it !in graph.reachable
        }.map {
            "remove block B${it + 1}"
        }.toMutableList()
        var code = mutableListOf<CodeLine>()
        val labels = mutableListOf<CodeLine>()
        var number = 0
        for (line in function.code) {
            if (line is CodeLine.Label) labels.add(line) else {
                if (graph.owners[number] in graph.reachable) {
                    code.addAll(labels)
                    code.add(line)
                }
                labels.clear()
                number++
            }
        }
        val deleted = mutableSetOf<Int>()
        number = 0
        for ((i, line) in code.withIndex()) {
            if (line is CodeLine.Code) {
                number++
                if (line.instruction.kind in listOf("goto", "if")) {
                    var j = i + 1
                    while (j < code.size && code[j] is CodeLine.Label) {
                        if ((code[j] as CodeLine.Label).name == line.instruction.target) {
                            deleted.add(i)
                            records.add("remove jump #$number")
                            break
                        }
                        j++
                    }
                }
            }
        }
        code = code.filterIndexed {
            i, _ -> i !in deleted
        }.toMutableList()
        val targets = code.mapNotNull {
            if (it is CodeLine.Code && it.instruction.kind in listOf("goto", "if")) it.instruction.target else null
        }.toSet()
        function.code = code.filter {
            if (it is CodeLine.Label && it.name !in targets) {
                records.add("remove label " + it.name)
                false
            } else true
        }
        return records
    }
}

import java.math.BigInteger
data class Allocation(val nodes: List<String>, val neighbors: Map<String, Set<String>>, val costs: Map<String, BigInteger>, val order: List<String>, val potential: List<Pair<String, Int>>, val registers: Map<String, Int>, val spills: Set<String>)
object Regalloc {
    fun allocate(function: Function, graph: Graph, analysis: Analysis, count: Int): Allocation {
        val nodes = function.parameters.toMutableSet()
        for ((i, instruction) in graph.instructions.withIndex()) {
            if (graph.owners[i] in graph.reachable) {
                instruction.destination?.let {
                    nodes.add(it)
                }
                nodes.addAll(instruction.used)
            }
        }
        val sorted = nodes.sorted()
        val neighbors = sorted.associateWith {
            mutableSetOf<String>()
        }.toMutableMap()
        val costs = sorted.associateWith {
            BigInteger.ZERO
        }.toMutableMap()
        val partners = mutableMapOf<String, MutableSet<String>>()
        fun edge(a: String, b: String) {
            if (a != b) {
                neighbors.getValue(a).add(b)
                neighbors.getValue(b).add(a)
            }
        }
        for (b in graph.reachable) {
            var live = analysis.live.output[b]
            for (i in graph.blocks[b].last downTo graph.blocks[b].first) {
                val instruction = graph.instructions[i]
                val x = instruction.destination
                if (x != null) {
                    for (v in live) {
                        if (v != x && !(instruction.kind == "copy" && instruction.a?.variable == v)) edge(x, v)
                    }
                }
                live = Transfer.live(live, instruction)
            }
            val weight = BigInteger.TEN.pow(graph.depths[b])
            for (i in graph.blocks[b].first..graph.blocks[b].last) {
                val instruction = graph.instructions[i]
                for (v in instruction.used + listOfNotNull(instruction.destination)) costs[v] = costs.getValue(v).add(weight)
            }
        }
        val initial = analysis.live.input[0] + function.parameters
        for (p in function.parameters) {
            costs[p] = costs.getValue(p).add(BigInteger.ONE)
            for (v in initial) if (v != p) edge(p, v)
        }
        for (instruction in graph.instructions) {
            val x = instruction.destination
            val y = instruction.a?.variable
            if (instruction.kind == "copy" && x != null && y != null && x != y) {
                partners.getOrPut(x) {
                    mutableSetOf()
                }.add(y)
                partners.getOrPut(y) {
                    mutableSetOf()
                }.add(x)
            }
        }
        val remaining = nodes.toMutableSet()
        val order = mutableListOf<String>()
        val potential = mutableListOf<Pair<String, Int>>()
        while (remaining.isNotEmpty()) {
            val degrees = remaining.associateWith {
                neighbors.getValue(it).count {
                    neighbor -> neighbor in remaining
                }
            }
            val low = remaining.filter {
                degrees.getValue(it) < count
            }
            val chosen: String
            if (low.isNotEmpty()) chosen = low.minWith(compareBy<String> {
                degrees.getValue(it)
            }.thenBy {
                it
            })
            else {
                chosen = remaining.minWith(Comparator {
                    a, b -> val x = costs.getValue(a).multiply(BigInteger.valueOf(degrees.getValue(b).toLong()))
                    val y = costs.getValue(b).multiply(BigInteger.valueOf(degrees.getValue(a).toLong()))
                    val comparison = x.compareTo(y)
                    if (comparison == 0) a.compareTo(b) else comparison
                })
                potential.add(chosen to degrees.getValue(chosen))
            }
            order.add(chosen)
            remaining.remove(chosen)
        }
        val registers = mutableMapOf<String, Int>()
        val spills = mutableSetOf<String>()
        for (node in order.asReversed()) {
            val occupied = neighbors.getValue(node).mapNotNull {
                registers[it]
            }.toSet()
            val free = (0 until count).filter {
                it !in occupied
            }
            if (free.isEmpty()) {
                spills.add(node)
                continue
            }
            val biased = (partners[node] ?: emptySet()).mapNotNull {
                registers[it]
            }.filter {
                it in free
            }
            registers[node] = biased.minOrNull() ?: free[0]
        }
        return Allocation(sorted, neighbors.mapValues {
            it.value.toSet()
        }, costs.toMap(), order, potential, registers, spills)
    }
}

sealed interface Operand {
    data class Constant(val value: Long) : Operand
    data class Variable(val name: String) : Operand
    val text: String get() = when (this) {
        is Constant -> value.toString()
        is Variable -> name
    }
    val variable: String? get() = (this as? Variable)?.name
    val constant: Long? get() = (this as? Constant)?.value
    companion object {
        fun parse(text: String): Operand = if (text[0] == '-' || text[0] in '0'..'9') Constant(text.toLong()) else Variable(text)
    }
}
data class TacExpression(val kind: String, val operation: String, val a: Operand, val b: Operand?) {
    val text: String get() = if (kind == "load") "$operation[${a.text}]" else a.text + operation + b!!.text
    fun uses(name: String): Boolean = a.variable == name || b?.variable == name
}
data class Instruction(var kind: String, var destination: String? = null, var a: Operand? = null, var b: Operand? = null, var operation: String = "", var target: String = "", var array: String = "", var function: String = "", var count: Int = 0) {
    val operands: List<Operand> get() = listOfNotNull(a, b)
    val used: List<String> get() = operands.mapNotNull {
        it.variable
    }
    val expression: TacExpression? get() = if (kind in listOf("bin", "load")) TacExpression(kind, if (kind == "bin") operation else array, a!!, b) else null
    val text: String get() {
        val left = a?.text ?: ""
        val right = b?.text ?: ""
        val d = destination ?: ""
        return when (kind) {
            "copy" -> "$d = $left"
            "bin" -> "$d = $left $operation $right"
            "load" -> "$d = $array[$left]"
            "store" -> "$array[$left] = $right"
            "goto" -> "goto $target"
            "if" -> "if $left $operation $right goto $target"
            "read" -> "read $d"
            "return" -> if (a == null) "return" else "return $left"
            "call" -> (if (destination == null) "" else "$d = ") + "call $function $count"
            else -> "$kind $left"
        }
    }
    companion object {
        fun move(destination: String, a: Operand): Instruction = Instruction("copy", destination, a)
    }
}
sealed interface CodeLine {
    data class Label(val name: String) : CodeLine
    data class Code(val instruction: Instruction) : CodeLine
}
data class Function(val name: String, var parameters: List<String>, var code: List<CodeLine>, var temporary: Int = 0, var preheader: Int = 0) {
    val instructions: List<Instruction> get() = code.mapNotNull {
        (it as? CodeLine.Code)?.instruction
    }
    val text: List<String> get() = listOf("func " + name + parameters.joinToString("") {
        " $it"
    }) + code.map {
        when (it) {
            is CodeLine.Label -> it.name + ":"
            is CodeLine.Code -> "    " + it.instruction.text
        }
    } + "end"
    fun deepCopy(): Function = copy(parameters = parameters.toList(), code = code.map {
        if (it is CodeLine.Code) CodeLine.Code(it.instruction.copy()) else it
    })
}
data class Program(val arrays: List<Pair<String, Int>>, var functions: List<Function>) {
    val text: List<String> get() {
        val lines = arrays.map {
            "array ${it.first} ${it.second}"
        }.toMutableList()
        for (function in functions) {
            if (lines.isNotEmpty()) lines.add("")
            lines.addAll(function.text)
        }
        return lines
    }
}
object TacParser {
    fun indexed(text: String): Pair<String, Operand> {
        val i = text.indexOf('[')
        return text.substring(0, i) to Operand.parse(text.substring(i + 1, text.length - 1))
    }
    fun parse(text: String): Program {
        val arrays = mutableListOf<Pair<String, Int>>()
        val functions = mutableListOf<Function>()
        for (line in text.lineSequence()) {
            val w = line.split(' ').filter {
                it.isNotEmpty()
            }
            if (w.isEmpty() || w[0].startsWith("#")) continue
            if (w[0] == "array") {
                arrays.add(w[1] to w[2].toInt())
                continue
            }
            if (w[0] == "func") {
                functions.add(Function(w[1], w.drop(2), emptyList()))
                continue
            }
            if (w[0] == "end") continue
            val f = functions.last()
            if (w.size == 1 && w[0].endsWith(":")) {
                f.code = f.code + CodeLine.Label(w[0].dropLast(1))
                continue
            }
            val instruction = Instruction("copy")
            when (w[0]) {
                "goto" -> {
                    instruction.kind = "goto"
                    instruction.target = w[1]
                }
                "if" -> {
                    instruction.kind = "if"
                    instruction.a = Operand.parse(w[1])
                    instruction.operation = w[2]
                    instruction.b = Operand.parse(w[3])
                    instruction.target = w[5]
                }
                "param", "return", "read", "print" -> {
                    instruction.kind = w[0]
                    if (w.size > 1) {
                        if (w[0] == "read") instruction.destination = w[1] else instruction.a = Operand.parse(w[1])
                    }
                }
                else -> if ('[' in w[0]) {
                    instruction.kind = "store"
                    val (array, index) = indexed(w[0])
                    instruction.array = array
                    instruction.a = index
                    instruction.b = Operand.parse(w[2])
                }
                else {
                    val start = if (w[0] == "call") 0 else 2
                    if (start == 2) instruction.destination = w[0]
                    if (w[start] == "call") {
                        instruction.kind = "call"
                        instruction.function = w[start + 1]
                        instruction.count = w[start + 2].toInt()
                    }
                    else if (w.size == 5) {
                        instruction.kind = "bin"
                        instruction.a = Operand.parse(w[2])
                        instruction.operation = w[3]
                        instruction.b = Operand.parse(w[4])
                    }
                    else if ('[' in w[2]) {
                        instruction.kind = "load"
                        val (array, index) = indexed(w[2])
                        instruction.array = array
                        instruction.a = index
                    }
                    else instruction.a = Operand.parse(w[2])
                }
            }
            f.code = f.code + CodeLine.Code(instruction)
        }
        return Program(arrays, functions)
    }
    fun operation(op: String, a: Long, b: Long): Long = when (op) {
        "+" -> a + b
        "-" -> a - b
        "*" -> a * b
        "/" -> a / b
        "%" -> a % b
        "<" -> if (a < b) 1 else 0
        "<=" -> if (a <= b) 1 else 0
        ">" -> if (a > b) 1 else 0
        ">=" -> if (a >= b) 1 else 0
        "==" -> if (a == b) 1 else 0
        else -> if (a != b) 1 else 0
    }
    fun labels(function: Function): Map<String, Int> {
        val labels = mutableMapOf<String, Int>()
        var index = 0
        for (line in function.code) {
            when (line) {
                is CodeLine.Label -> labels[line.name] = index
                is CodeLine.Code -> index++
            }
        }
        return labels
    }
}
